from fastapi import FastAPI, Body
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float

@app.post("/items")
async def create_item(item: Item = Body(..., strict_content_type=True)):
    return item

client = TestClient(app)

def test_strict_content_type_success():
    response = client.post("/items", json={"name": "Foo", "price": 10.5})
    assert response.status_code == 200
    assert response.json() == {"name": "Foo", "price": 10.5}

def test_strict_content_type_fail_no_header():
    # Send JSON but without content-type header
    response = client.post(
        "/items", 
        content='{"name": "Foo", "price": 10.5}', 
        headers={}
    )
    # Should fail because strict_content_type=True and no header
    assert response.status_code == 422

def test_strict_content_type_fail_wrong_header():
    # Send JSON but with wrong content-type header
    response = client.post(
        "/items", 
        content='{"name": "Foo", "price": 10.5}', 
        headers={"content-type": "text/plain"}
    )
    # Should fail because strict_content_type=True and wrong header
    assert response.status_code == 422

@app.post("/items-lax")
async def create_item_lax(item: Item = Body(..., strict_content_type=False)):
    return item

def test_lax_content_type_success_no_header():
    response = client.post(
        "/items-lax", 
        content='{"name": "Foo", "price": 10.5}', 
        headers={}
    )
    assert response.status_code == 200
    assert response.json() == {"name": "Foo", "price": 10.5}

def test_lax_content_type_success_wrong_header():
    response = client.post(
        "/items-lax", 
        content='{"name": "Foo", "price": 10.5}', 
        headers={"content-type": "text/plain"}
    )
    assert response.status_code == 200
    assert response.json() == {"name": "Foo", "price": 10.5}

if __name__ == "__main__":
    import pytest
    # This is a simple script, we can just call the functions
    try:
        test_strict_content_type_success()
        print("test_strict_content_type_success passed")
        test_strict_content_type_fail_no_header()
        print("test_strict_content_type_fail_no_header passed")
        test_strict_content_type_fail_wrong_header()
        print("test_strict_content_type_fail_wrong_header passed")
        test_lax_content_type_success_no_header()
        print("test_lax_content_type_success_no_header passed")
        test_lax_content_type_success_wrong_header()
        print("test_lax_content_type_success_wrong_header passed")
        print("All tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")

